    try { localStorage.setItem(HUB_TEAMS_STORAGE_KEY, JSON.stringify(cachedHubTeams().filter(function(team){return team.teamId!==teamId;}))); } catch(_hubTeamsStorageError) {}
    delete WORKSPACE_OPTIONS[key];
