  function renderLocalBrowser(){
    var overlay = el('#localBrowserOverlay');
    var empty = el('#localBrowserEmpty');
    var blocked = el('#localBrowserBlocked');
    var back = el('#localBrowserBackBtn');
    var forward = el('#localBrowserForwardBtn');
    var reload = el('#localBrowserReloadBtn');
    if(!overlay) return;
    overlay.hidden = !localBrowserState.open;
    overlay.setAttribute('aria-hidden', localBrowserState.open ? 'false' : 'true');
    overlay.classList.toggle('open', localBrowserState.open);
    if(window.miaNativeBrowser){ window.miaNativeBrowser.render(localBrowserState.open); syncBrowserSuggestNext(); return; }
    if(empty) empty.hidden = true;
    if(blocked) blocked.hidden = false;
    var blockedTitle = el('#localBrowserBlockedTitle');
    var blockedMessage = el('#localBrowserBlockedMessage');
    var blockedLink = el('#localBrowserBlockedLink');
    if(blockedTitle) blockedTitle.textContent = 'Native browser unavailable';
    if(blockedMessage) blockedMessage.textContent = 'Open this localhost build in Mia to use its browser.';
    if(blockedLink) blockedLink.hidden = true;
    if(back) back.disabled = true;
    if(forward) forward.disabled = true;
    if(reload) reload.disabled = true;
  }

  function localBrowserNavigate(value){
    var target;
    try { target = localBrowserNormalizeUrl(value, localBrowserSearchEngine); }
    catch(error){ showBenchToast(error.message || 'Enter a valid web address.'); return false; }
    if(window.miaNativeBrowser) return window.miaNativeBrowser.navigate(target);
    showBenchToast('The browser is available only in Mia.');
    return false;
  }

  function closeLocalBrowser(){
    if(!localBrowserState.open) return;
    stopLocalBrowserPromptRotation();
    localBrowserState.open = false;
    localBrowserState.roomId = null;
    localBrowserHistoryCache = null;
    closeLocalBrowserSuggest();
    try {
      if(window.miaDesktop && window.miaDesktop.state) window.miaDesktop.state.set(LOCAL_BROWSER_OPEN_STATE_KEY, null);
    } catch(_browserDesktopStateError) {}
    try { localStorage.removeItem(LOCAL_BROWSER_OPEN_STATE_KEY); } catch(_browserStorageError) {}
    document.body.classList.remove('browser-collab-mode', 'browser-sidebar-open');
    applyLeftPane();
    renderLocalBrowser();
    syncInlineChatSuggestion();
  }

  function openWebBrowserTool(options){
    closeAutomationsPage();
    closeArtifactsPage();
    closeAppsPage();
    localBrowserState.open = true;
    try {
      if(window.miaDesktop && window.miaDesktop.state) window.miaDesktop.state.set(LOCAL_BROWSER_OPEN_STATE_KEY, '1');
    } catch(_browserDesktopStateError) {}
    try { localStorage.setItem(LOCAL_BROWSER_OPEN_STATE_KEY, '1'); } catch(_browserStorageError) {}
    document.body.classList.add('browser-collab-mode');
    setBrowserSidebarOpen(browserSidebarWanted());
    closeChatThread();
    closeChatTasksPanel();
    chatInfo.mode = 'automations';
    chatInfo.open = false;
    // Opening the browser used to always yank the chat pane back to the
    // gateway room. If an agent/bot room is already active, keep the chat
    // pane pinned to it instead — only fall back to the gateway room when
    // nothing is active yet.
    if(chatWs.activeRoomId){
      localBrowserState.roomId = chatWs.activeRoomId;
    } else if(chatWs.gatewayAgent){
      navigateToAgentChat(chatWs.gatewayAgent, true);
      localBrowserState.roomId = chatWs.activeRoomId || chatWs.gatewayAgent.roomId || chatWs.gatewayAgent.nativeConversationId || null;
    }
    renderChatInfoPane();
    renderChatHeaderBar();
    renderLocalBrowser();
    browserFollowKey = '';
    // From a bot's chat, the browser opens on that bot's tabs instead of
    // following whatever tab was active (often Mia's) back to Mia.
    var botId = options && options.forActiveBot ? activeChatBotId() : null;
    if(botId) openBrowserForBot(botId);
    else followBrowserTab(null);
    startLocalBrowserPromptRotation();
    if(options && options.restoring) showBenchToast('Browser restored where you left off. Playback is paused.');
  }

  function activeChatBotId(){
    var owner = activeConversationOwner();
    return owner && owner.indexOf('bot:') === 0 ? owner.slice(4) : null;
  }

  // Selects the bot's most recent tab, or opens a new tab in a new group
  // assigned to the bot when it has none yet.
  function openBrowserForBot(botId){
    var browser = window.miaDesktop && window.miaDesktop.browser;
    if(!browser || !browser.command){ followBrowserTab(null); return; }
    var bot = browserBotRecord(botId);
    browser.command({ action: 'state' }).then(function(state){
      var tab = botBrowserTab(state, botId);
      if(tab) return browser.command({ action: 'select', id: tab.id });
      // An empty tab nobody owns (the browser always keeps one) becomes the
      // bot's tab instead of sitting beside a second one.
      var blank = (state && state.tabs || []).filter(function(t){ return !t.groupId && !t.url; })[0];
      var ready = blank
        ? browser.command({ action: 'select', id: blank.id })
        : browser.command({ action: 'new' });
      return ready.then(function(created){
        var id = blank ? blank.id : created && created.activeId;
        if(!id) return created;
        return browser.command({ action: 'groupCreate', id: id, name: bot && bot.name || '' }).then(function(grouped){
          var newTab = (grouped && grouped.tabs || []).filter(function(t){ return t.id === id; })[0];
          if(!newTab || !newTab.groupId) return grouped;
          return browser.command({ action: 'groupAssignBot', groupId: newTab.groupId, bot: { botId: botId, name: bot && bot.name || '' } });
        });
      });
    }).then(function(state){
      if(state && !state.error) followBrowserTab(state);
    }).catch(function(){ followBrowserTab(null); });
  }

  // Automations page: every bot's automations in the center with the chat
  // on the right, the same layout as the browser. Rows open a step page and
  // switch the chat to the bot that owns the automation.
  var AUTOMATIONS_GROUP_KEY = 'mia.automations.group';
  var automationsPage = {open:false, botId:null, automationId:null, group:'status', tabs:[], boardClosed:false};
  try { if(localStorage.getItem(AUTOMATIONS_GROUP_KEY) === 'bot') automationsPage.group = 'bot'; } catch(_automationsGroupError) {}

  function automationsBoardRows(){
    if(!window.MiaAutomationsBoard) return [];
    return window.MiaAutomationsBoard.entries(chatWs.botRecords || [], chatWs.automationRuns || [], automationScheduleText, chatWs.automationChecklists || []);
  }

  function automationsRowHtml(row){
    var side = row.status === 'running' ? '<span class="automations-live" aria-hidden="true"></span>Running'
      : row.status === 'needs' ? 'Review' : '';
    return '<button type="button" class="automations-row" data-status="' + esc(row.status) + '" data-automations-bot="' + esc(row.botId) + '" data-automations-id="' + esc(row.automationId) + '">' +
      '<span class="automations-row-avatar">' + agentAvatarHtml(row.botName, row.botId, 24, 'static', row.color) +
        (row.status === 'needs' ? '<span class="automations-row-blocked">Blocked</span>' : '') + '</span>' +
      '<span><div class="automations-row-name">' + esc(automationsPage.group === 'bot' ? row.name : row.botName + ' · ' + row.name) + '</div>' +
      '<div class="automations-row-detail">' + esc(row.detail || '') + '</div></span>' +
      '<span class="automations-row-side">' + side + '</span></button>';
  }

  function automationsBoardHtml(rows){
    if(!rows.length) return '<div class="automations-empty">No automations yet. Ask a bot to do something on a schedule, like "every weekday at 9, send me the AI news", and it shows up here.</div>';
    return window.MiaAutomationsBoard.groups(rows, automationsPage.group).map(function(group){
      var dot = automationsPage.group === 'bot' ? '<span class="automations-group-dot" style="background:' + esc(normalizeAgentAvatarColor(group.color) || agentAvatarColorFor(group.title, group.botId) || '#999') + '"></span>' : '';
      return '<div class="automations-group-title">' + dot + esc(group.title) + '</div>' + group.rows.map(automationsRowHtml).join('');
    }).join('');
  }

  function automationsRunHistoryHtml(){
    var shelf = window.MiaViewShelf;
    automationsPage.runHistory = shelf ? shelf.runHistory(chatWs.automationRuns, chatWs.botRecords, botAutomationList) : [];
    if(!automationsPage.runHistory.length) return '';
    return '<div class="automations-group-title">Run history</div><div class="automations-run-history">' +
      shelf.rowsHtml(automationsPage.runHistory, esc, shelfWhen) + '</div>';
  }

  function automationStepStateLabel(state){
    return {working:'Working on it', done:'Done', skipped:'Skipped', failed:'Failed', needs_you:'Needs you', escalated:'Needs you', unreported:'Not reported', pending:'Not started'}[state] || '';
  }

  function automationRunTime(value){
    var numeric = Number(value);
    var date = Number.isFinite(numeric) && String(value).trim() !== '' ? new Date(numeric * (numeric < 10000000000 ? 1000 : 1)) : new Date(String(value));
    return isNaN(date.getTime()) ? '' : date.toLocaleString([], {dateStyle:'medium', timeStyle:'short'});
  }

  // The automation editor lists steps as numbered rows, like the
  // Automations page: five to start, and a new row appears once the last one
  // is filled. Enter moves to the next row; a pasted list fills one row per line.
  var AUTOMATION_STEP_EXAMPLES = ['Search the web for today\'s AI news', 'Pick the 5 that matter most', 'Post the briefing here'];
  var AUTOMATION_STEP_MAX = 20;
  function automationStepRowHtml(n, value, placeholder){
    return '<li class="cip-automation-step"><span class="cip-automation-step-n">' + n + '</span>' +
      '<input type="text" maxlength="500" aria-label="Step ' + n + '" value="' + esc(value || '') + '"' + (placeholder ? ' placeholder="' + esc(placeholder) + '"' : '') + '></li>';
  }
  function automationStepRowsHtml(steps){
    var list = steps.map(function(step){ return String(step || '').trim(); }).filter(Boolean);
    var count = Math.min(AUTOMATION_STEP_MAX, Math.max(5, list.length + 1));
    var html = '';
    for(var i = 0; i < count; i++) html += automationStepRowHtml(i + 1, list[i], list.length ? '' : AUTOMATION_STEP_EXAMPLES[i]);
    return html;
  }
  function automationStepRowValues(list){
    return els('input', list).map(function(input){ return input.value.trim(); }).filter(Boolean);
  }
  function wireAutomationStepRows(list){
    if(!list) return;
    function inputs(){ return els('input', list); }
    function addRow(){
      var count = inputs().length;
      if(count >= AUTOMATION_STEP_MAX) return null;
      list.insertAdjacentHTML('beforeend', automationStepRowHtml(count + 1, '', ''));
      return inputs()[count];
    }
    function renumber(){
      els('.cip-automation-step', list).forEach(function(row, index){
        el('.cip-automation-step-n', row).textContent = index + 1;
        el('input', row).setAttribute('aria-label', 'Step ' + (index + 1));
      });
    }
    list.addEventListener('input', function(){
      var all = inputs();
      if(all[all.length - 1].value.trim()) addRow();
    });
    list.addEventListener('paste', function(event){
      var text = event.clipboardData && event.clipboardData.getData('text') || '';
      var lines = text.split(/\r?\n/).map(function(line){ return line.trim(); }).filter(Boolean);
      if(lines.length < 2) return;
      event.preventDefault();
      var index = inputs().indexOf(event.target);
      lines.forEach(function(line, offset){
        var input = inputs()[index + offset] || addRow();
        if(input) input.value = line;
      });
      var all = inputs();
      if(all[all.length - 1].value.trim()) addRow();
    });
    list.addEventListener('keydown', function(event){
      var all = inputs();
      var index = all.indexOf(event.target);
      if(index < 0) return;
      if(event.key === 'Enter'){
        event.preventDefault();
        var next = all[index + 1] || addRow();
        if(next) next.focus();
      } else if(event.key === 'Backspace' && !event.target.value && index > 0){
        event.preventDefault();
        var previous = all[index - 1];
        if(all.length > 5) { event.target.parentNode.remove(); renumber(); }
        previous.focus();
      }
    });
  }

  function automationsDetailHtml(row, automation, bot){
    // The side stays short so the title keeps its width; what needs the
    // person shows in full under it, with a way to hand it to Mia.
    var side = row.status === 'running' ? '<span class="automations-live" aria-hidden="true"></span>Running now'
      : row.status === 'needs' ? 'Needs you' : row.status === 'paused' ? 'Paused' : '';
    var needs = row.status === 'needs' && row.detail ? '<div class="automations-needs"><p>' + esc(row.detail) + '</p>' +
      '<button type="button" class="styled-btn-secondary" id="automationsFix">Fix with Mia</button></div>' : '';
    var body;
    var checklist = row.checklist;
    if(row.steps.length){
      // With a run on record, each step shows what the bot reported for it.
      var states = {};
      if(checklist) (checklist.steps || []).forEach(function(item){ states[item.n] = item; });
      body = '<ol class="automations-steps">' + row.steps.map(function(step, index){
        var item = states[index + 1];
        var state = item ? item.state : '';
        var mark = state ? '<span class="automations-step-mark" data-state="' + esc(state) + '" title="' + esc(automationStepStateLabel(state)) + '"></span>' : '';
        var note = item && item.note ? '<div class="automations-step-note">' + esc(item.note) + '</div>' : '';
        return '<li class="automations-step" data-state="' + esc(state) + '"><span class="automations-step-n">' + mark + (index + 1) + '</span><span>' + esc(step) + note + '</span></li>';
      }).join('') + '</ol>';
      if(checklist && checklist.startedAt){
        var when = automationRunTime(checklist.startedAt);
        var progress = checklist.runStatus === 'claimed' || checklist.runStatus === 'running' ? 'This run' : 'Last run';
        body += '<p class="automations-note">' + esc(progress + (when ? ' started ' + when : '') + ' · ' + checklist.done + ' of ' + checklist.total + ' steps done') + '</p>';
      }
    } else if(String(automation.prompt || '').trim()){
      body = '<div class="automations-instructions">' + esc(automation.prompt) + '</div>' +
        '<p class="automations-note">This runs as one instruction. Split it into steps so the bot does them one at a time, in order.</p>';
    } else {
      body = '<p class="automations-note">No steps yet. Add the steps this automation should follow.</p>';
    }
    var delivery = bot && bot.hermesCronDeliveries && bot.hermesCronDeliveries[automation.id];
    var last = delivery && delivery.deliveredAt ? '<p class="automations-note">Last result posted ' + esc(new Date(delivery.deliveredAt).toLocaleString([], {dateStyle:'medium', timeStyle:'short'})) + '</p>' : '';
    return '<div class="automations-detail-head"><div><div class="automations-detail-title">' + esc(row.name) + '</div>' +
      '<div class="automations-detail-sub">' + esc([row.schedule, row.botName].filter(Boolean).join(' · ')) + '</div></div>' +
      '<span class="automations-row-side">' + side + '</span></div>' + needs + body + last +
      '<div class="automations-actions"><button type="button" class="styled-btn-secondary" id="automationsEdit">' + (row.steps.length ? 'Edit' : 'Add steps') + '</button></div>';
  }

  function renderAutomationsPage(){
    var overlay = el('#automationsOverlay');
    if(!overlay) return;
    overlay.hidden = !automationsPage.open;
    overlay.setAttribute('aria-hidden', automationsPage.open ? 'false' : 'true');
    overlay.classList.toggle('open', automationsPage.open);
    var rows = automationsBoardRows();
    // Closed, its tabs still show in the mixed strip, so a closed tab leaves it.
    if(!automationsPage.open){ renderAutomationsTabs(rows); return; }
    var summary = el('#automationsSummary');
    if(summary) summary.textContent = window.MiaAutomationsBoard ? window.MiaAutomationsBoard.summary(rows) : '';
    els('[data-automations-group]', overlay).forEach(function(button){
      button.setAttribute('aria-pressed', button.getAttribute('data-automations-group') === automationsPage.group ? 'true' : 'false');
    });
    var toggle = el('#automationsGroupToggle');
    var row = automationsPage.automationId ? rows.filter(function(item){
      return item.botId === automationsPage.botId && item.automationId === automationsPage.automationId;
    })[0] : null;
    var found = row && automationRecordById(row.botId, row.automationId);
    if(automationsPage.automationId && !found){ automationsPage.botId = null; automationsPage.automationId = null; }
    renderAutomationsTabs(rows);
    if(toggle) toggle.hidden = !!found;
    var body = el('#automationsBody');
    if(!body) return;
    var scroll = body.scrollTop;
    // Team workflows sit above the bot automations, in team workspaces only.
    var teamWorkflows = !found && hubWorkspace() && window.MiaTeamWorkflowsUi ? window.MiaTeamWorkflowsUi : null;
    body.innerHTML = '<div class="automations-content">' + (teamWorkflows ? '<div id="teamWorkflowsMount"></div>' : '')
      + (found ? automationsDetailHtml(row, found.automation, found.bot) : '<div data-wf-board>' + automationsBoardHtml(rows) + '</div>' + automationsRunHistoryHtml()) + '</div>';
    if(teamWorkflows) teamWorkflows.mountInto(el('#teamWorkflowsMount', body));
    if(!found) body.scrollTop = scroll;
    els('[data-automations-id]', body).forEach(function(button){
      button.addEventListener('click', function(){
        openAutomationsDetail(button.getAttribute('data-automations-bot'), button.getAttribute('data-automations-id'));
      });
    });
    els('[data-shelf-row]', body).forEach(function(button){
      button.addEventListener('click', function(){
        var run = automationsPage.runHistory[Number(button.getAttribute('data-shelf-row'))];
        if(run) openAutomationsDetail(run.botId, run.automationId);
      });
    });
    var edit = el('#automationsEdit', body);
    if(edit && found) edit.addEventListener('click', function(){ openAutomationDetail(found.bot.id, found.automation.id); });
    var fix = el('#automationsFix', body);
    if(fix && found) fix.addEventListener('click', function(){ fixAutomationWithMia(row, fix); });
  }

  // What the automation page knows about a stuck automation, sent to Mia as
  // a message in her chat so she can find the cause and fix it.
  function automationFixMessage(row){
    var steps = (row.steps || []).slice(0, 12).map(function(step, index){
      return (index + 1) + '. ' + String(step).replace(/\s+/g, ' ').slice(0, 300);
    });
    return ['Fix this automation so it can run again.',
      'Automation: ' + row.name + ' (bot: ' + (row.botName || 'unknown') + (row.schedule ? ', ' + row.schedule : '') + '; bot id ' + row.botId + ', automation id ' + row.automationId + ')',
      'Problem: ' + String(row.detail || '').replace(/\s+/g, ' ')]
      .concat(steps.length ? ['Steps:'].concat(steps) : [])
      .concat(['Find the cause and fix it, for example by reconnecting what is missing or changing the automation. If something only I can do, tell me exactly what.'])
      .join('\n');
  }
  function fixAutomationWithMia(row, button){
    var text = automationFixMessage(row);
    if(button) button.disabled = true;
    var mia = (chatWs.nativeConversations || []).filter(isNativeMiaConversation)[0];
    var ready = mia ? Promise.resolve(chatWs.nativeConversations) : ensureNativeMiaConversation(chatWs.nativeConversations || []);
    return ready.then(function(list){
      mia = (list || []).filter(isNativeMiaConversation)[0];
      if(!mia) throw new Error('Mia\'s chat is not available right now. Try again.');
      if(list !== chatWs.nativeConversations) chatWs.nativeConversations = list;
      if(window.MiaTabStrip) window.MiaTabStrip.mix.open('chat');
      return Promise.resolve(loadChatRoom(mia.id, 'agent', 'Mia')).then(function(){
        return sendNativeConversationEvent(text, null, null, mia.id);
      });
    }).catch(function(error){
      showToast(error && error.message || 'Could not reach Mia. Try again.');
    }).finally(function(){ if(button) button.disabled = false; });
  }

  // Automations tabs: the board is the first tab; each automation opened
  // from it gets a tab.
  var AUTOMATIONS_BOARD_TAB = 'board';
  function automationsTabId(botId, automationId){ return String(botId) + '|' + String(automationId); }
  var AUTOMATIONS_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 12h4l3-8 4 16 3-8h4"></path></svg>';
  function automationsTabById(id){
    return automationsPage.tabs.filter(function(tab){ return automationsTabId(tab.botId, tab.automationId) === id; })[0] || null;
  }
  // Automations tabs live in the browser's tab strip (native-browser.js),
  // which sits in the Automations row while the page shows.
  var automationsStripTabs = null;
  function renderAutomationsTabs(rows){
    // An automation that was deleted takes its tab with it.
    automationsPage.tabs = automationsPage.tabs.filter(function(tab){ return !!automationRecordById(tab.botId, tab.automationId); });
    var activeId = !automationsPage.open ? null : automationsPage.automationId ? automationsTabId(automationsPage.botId, automationsPage.automationId) : AUTOMATIONS_BOARD_TAB;
    // The board's tab closes like any other; the Automations button opens it again.
    var board = automationsPage.boardClosed ? [] : [{id:AUTOMATIONS_BOARD_TAB, label:'Automations', iconHtml:AUTOMATIONS_ICON, active:activeId === AUTOMATIONS_BOARD_TAB}];
    automationsStripTabs = board
      .concat(automationsPage.tabs.map(function(tab){
        var id = automationsTabId(tab.botId, tab.automationId);
        var row = rows.filter(function(item){ return item.botId === tab.botId && item.automationId === tab.automationId; })[0];
        var name = row ? row.name : (automationRecordById(tab.botId, tab.automationId).automation.name || 'Automation');
        return {id:id, label:name, title:row ? row.botName + ' \u00b7 ' + name : name, active:id === activeId,
          iconHtml:row ? agentAvatarHtml(row.botName, row.botId, 18, 'static', row.color) : AUTOMATIONS_ICON};
      }));
    window.MiaTabStrip.mix.notify('automations', JSON.stringify(automationsStripTabs));
  }
  function moveAutomationsTab(id, targetId){
    var tabs = automationsPage.tabs;
    var from = tabs.findIndex(function(tab){ return automationsTabId(tab.botId, tab.automationId) === id; });
    var to = tabs.findIndex(function(tab){ return automationsTabId(tab.botId, tab.automationId) === targetId; });
    if(targetId === AUTOMATIONS_BOARD_TAB) to = 0;
    if(from < 0 || to < 0 || from === to) return;
    tabs.splice(to, 0, tabs.splice(from, 1)[0]);
    renderAutomationsPage();
  }
  // Mixed tabs: the board and each open automation, shown in the other strips.
  window.MiaTabStrip.mix.register('automations', {
    tabs: function(){
      if(automationsStripTabs) return automationsStripTabs;
      return (automationsPage.boardClosed ? [] : [{id:AUTOMATIONS_BOARD_TAB, label:'Automations', iconHtml:AUTOMATIONS_ICON}]).concat(automationsPage.tabs.map(function(tab){
        var record = automationRecordById(tab.botId, tab.automationId);
        return {id:automationsTabId(tab.botId, tab.automationId), label:record && record.automation.name || 'Automation', iconHtml:AUTOMATIONS_ICON};
      }));
    },
    attention: function(){ return window.MiaNeedsYou.count(needsYouItems(), 'automations'); },
    close: closeAutomationsTab,
    move: moveAutomationsTab,
    show: function(){ if(!automationsPage.open) runToolsAction('automations'); },
    select: function(id){
      if(id === AUTOMATIONS_BOARD_TAB) showAutomationsBoard();
      else { var tab = automationsTabById(id); if(tab) openAutomationsDetail(tab.botId, tab.automationId); }
    },
    render: function(){ if(automationsPage.open) renderAutomationsTabs(automationsBoardRows()); },
  });
  function showAutomationsBoard(){
    automationsPage.boardClosed = false;
    automationsPage.botId = null;
    automationsPage.automationId = null;
    if(chatWs.gatewayAgent) navigateToAgentChat(chatWs.gatewayAgent, true);
    renderAutomationsPage();
  }
  // Closing the tab you are on shows the tab to its left, as in a browser;
  // with no Automations tab left, the page closes.
  function closeAutomationsTab(id){
    if(id === AUTOMATIONS_BOARD_TAB){
      automationsPage.boardClosed = true;
      // Closed from another view's strip, it just leaves the strip.
      if(!automationsPage.open || automationsPage.automationId){ renderAutomationsPage(); return; }
      var first = automationsPage.tabs[0];
      if(first) openAutomationsDetail(first.botId, first.automationId);
      else closeAutomationsPage();
      return;
    }
    var index = automationsPage.tabs.findIndex(function(tab){ return automationsTabId(tab.botId, tab.automationId) === id; });
    if(index < 0) return;
    automationsPage.tabs.splice(index, 1);
    if(automationsPage.automationId && automationsTabId(automationsPage.botId, automationsPage.automationId) === id){
      var left = automationsPage.tabs[index - 1] || (automationsPage.boardClosed ? automationsPage.tabs[index] : null);
      if(left) openAutomationsDetail(left.botId, left.automationId);
      else if(automationsPage.boardClosed) closeAutomationsPage();
      else showAutomationsBoard();
      return;
    }
    renderAutomationsPage();
  }

  // Opening an automation only changes the middle. The chat on the right stays
  // on whatever conversation was open: an automation can have many bots, so
  // none of them is "its" chat. Explicit actions (Fix with Mia, a running
  // automation's row) still open a chat themselves.
  function openAutomationsDetail(botId, automationId){
    automationsPage.botId = String(botId);
    automationsPage.automationId = String(automationId);
    if(!automationsTabById(automationsTabId(botId, automationId))) automationsPage.tabs.push({botId:String(botId), automationId:String(automationId)});
    renderAutomationsPage();
    var body = el('#automationsBody');
    if(body) body.scrollTop = 0;
  }

  function openAutomationsPage(){
    closeLocalBrowser();
    closeArtifactsPage();
    closeAppsPage();
    automationsPage.open = true;
    automationsPage.boardClosed = false;
    automationsPage.botId = null;
    automationsPage.automationId = null;
    document.body.classList.add('browser-collab-mode', 'automations-mode');
    setBrowserSidebarOpen(browserSidebarWanted());
    closeChatThread();
    closeChatTasksPanel();
    chatInfo.mode = 'automations';
    chatInfo.open = false;
    if(!chatWs.activeRoomId && chatWs.gatewayAgent) navigateToAgentChat(chatWs.gatewayAgent, true);
    renderChatInfoPane();
    renderChatHeaderBar();
    renderAutomationsPage();
    loadActiveAutomationRuns();
    if(hubWorkspace() && window.MiaTeamWorkflowsUi) window.MiaTeamWorkflowsUi.pageOpened();
  }

  function closeAutomationsPage(){
    if(!automationsPage.open) return;
    automationsPage.open = false;
    automationsPage.botId = null;
    automationsPage.automationId = null;
    document.body.classList.remove('automations-mode', 'browser-sidebar-open');
    if(!localBrowserState.open) document.body.classList.remove('browser-collab-mode');
    applyLeftPane();
    renderAutomationsPage();
    renderChatInfoPane();
    renderChatHeaderBar();
  }

  // Artifacts page: pages, documents and live apps you or your bots made,
  // laid out like Automations. Each one opens in its own browser tab.
  var artifactsPage = {open:false, items:[], filter:'all', query:'', loading:false, error:''};

  function openArtifactsPage(){
    closeLocalBrowser();
    closeAutomationsPage();
    closeAppsPage();
    artifactsPage.open = true;
    artifactsPage.tabClosed = false;
    document.body.classList.add('browser-collab-mode', 'artifacts-mode');
    setBrowserSidebarOpen(browserSidebarWanted());
    closeChatThread();
    closeChatTasksPanel();
    chatInfo.mode = 'automations';
    chatInfo.open = false;
    if(!chatWs.activeRoomId && chatWs.gatewayAgent) navigateToAgentChat(chatWs.gatewayAgent, true);
    renderChatInfoPane();
    renderChatHeaderBar();
    renderArtifactsPage();
    loadArtifacts();
  }

  // The page is one tab in the browser's strip, like the Automations board:
  // × closes the page; the Artifacts button opens it, and its tab, again.
  var ARTIFACTS_TAB = 'page';
  var ARTIFACTS_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="1.5"></rect><rect x="14" y="3" width="7" height="7" rx="1.5"></rect><rect x="3" y="14" width="7" height="7" rx="1.5"></rect><rect x="14" y="14" width="7" height="7" rx="1.5"></rect></svg>';
  function artifactsStripTabs(){
    return artifactsPage.tabClosed ? [] : [{id:ARTIFACTS_TAB, label:'Artifacts', iconHtml:ARTIFACTS_ICON, active:artifactsPage.open}];
  }
  window.MiaTabStrip.mix.register('artifacts', {
    tabs: artifactsStripTabs,
    // The tab is the page itself, so it adds no count to the button.
    count: function(){ return 0; },
    close: function(){
      artifactsPage.tabClosed = true;
      if(artifactsPage.open) closeArtifactsPage();
      else window.MiaTabStrip.mix.notify('artifacts', JSON.stringify(artifactsStripTabs()));
    },
    show: function(){ if(!artifactsPage.open) runToolsAction('artifacts'); },
    select: function(){},
    render: function(){ window.MiaTabStrip.mix.notify('artifacts', JSON.stringify(artifactsStripTabs())); },
  });

  function closeArtifactsPage(){
    if(!artifactsPage.open) return;
    artifactsPage.open = false;
    setArtifactsAddOpen(false);
    document.body.classList.remove('artifacts-mode', 'browser-sidebar-open');
    if(!localBrowserState.open) document.body.classList.remove('browser-collab-mode');
    applyLeftPane();
    renderArtifactsPage();
    renderChatInfoPane();
    renderChatHeaderBar();
  }

  function loadArtifacts(){
    artifactsPage.loading = true;
    artifactsPage.error = '';
    renderArtifactsPage();
    api('/api/artifacts').then(function(res){
      artifactsPage.loading = false;
      if(res.status !== 200) artifactsPage.error = 'Your artifacts could not be loaded. Try again.';
      else artifactsPage.items = Array.isArray(res.data.artifacts) ? res.data.artifacts : [];
      renderArtifactsPage();
    }).catch(function(){
      artifactsPage.loading = false;
      artifactsPage.error = 'Your artifacts could not be loaded. Try again.';
      renderArtifactsPage();
    });
  }

  // Your own saved apps show the icon their site has; the text label stays until one arrives.
  var siteIcons = {}, siteIconRequests = {};
  function showSiteIcon(thumb, icon){
    var image = document.createElement('img');
    image.alt = '';
    image.src = icon;
    thumb.textContent = '';
    thumb.appendChild(image);
    thumb.classList.add('has-site-icon');
  }
  function fillSiteIcons(root){
    var browser = window.miaDesktop && window.miaDesktop.browser;
    if(!root || !browser || !browser.command) return;
    Array.prototype.forEach.call(root.querySelectorAll('[data-site-url]'), function(thumb){
      var url = thumb.getAttribute('data-site-url');
      if(siteIcons[url]){ showSiteIcon(thumb, siteIcons[url]); return; }
      if(!siteIconRequests[url]){
        siteIconRequests[url] = Promise.resolve(browser.command({action: 'siteIcon', url: url})).catch(function(){ return null; }).then(function(res){
          var icon = res && /^data:image\//i.test(res.icon || '') ? res.icon : '';
          if(icon) siteIcons[url] = icon;
          // A site that was off or had no icon gets another try next time the list opens.
          delete siteIconRequests[url];
          return icon;
        });
      }
      siteIconRequests[url].then(function(icon){ if(icon && thumb.isConnected) showSiteIcon(thumb, icon); });
    });
  }

  function renderArtifactsPage(){
    var overlay = el('#artifactsOverlay');
    if(!overlay) return;
    window.MiaTabStrip.mix.notify('artifacts', JSON.stringify(artifactsStripTabs()));
    overlay.hidden = !artifactsPage.open;
    overlay.setAttribute('aria-hidden', artifactsPage.open ? 'false' : 'true');
    overlay.classList.toggle('open', artifactsPage.open);
    if(!artifactsPage.open || !window.MiaArtifactsPage) return;
    var chips = el('#artifactsChips');
    if(chips) chips.innerHTML = window.MiaArtifactsPage.chipsHtml(artifactsPage.items, artifactsPage.filter, esc);
    var body = el('#artifactsBody');
    if(body) body.innerHTML = window.MiaArtifactsPage.bodyHtml(Object.assign({}, artifactsPage, {recentIds: recentArtifactIds()}), esc);
    fillSiteIcons(body);
  }

  // Files open from the Mia folder (the browser previews nothing outside
  // it); live apps open by address.
  function openArtifact(id){
    var item = artifactsPage.items.filter(function(entry){ return entry.id === id; })[0];
    var browser = window.miaDesktop && window.miaDesktop.browser;
    if(!item) return;
    if(!browser || !browser.command){ showBenchToast('Artifacts open in the Mia desktop app.'); return; }
    var target = item.kind === 'app' ? item.url : item.path;
    rememberRecentArtifact(item.id);
    closeArtifactsPage();
    openAddressInBrowserTab(target, 'That artifact could not be opened.');
  }
  // A new tab in Mia's own browser, with this person's sign-ins.
  function openAddressInBrowserTab(target, failure){
    var browser = window.miaDesktop.browser;
    openWebBrowserTool();
    browser.command({action: 'new'}).then(function(){
      return browser.command({action: 'navigate', value: target});
    }).then(function(state){
      if(state && state.error) showBenchToast(state.error);
      followBrowserTab(state && !state.error ? state : null);
    }).catch(function(error){
      showBenchToast(error && error.message ? error.message : failure);
    });
  }

  // Sharing puts the artifact in the chat composer, the same as picking it
  // from (+) > Artifacts, so the person chooses the chat and adds a note.
  function shareArtifact(id){
    var item = artifactsPage.items.filter(function(entry){ return entry.id === id; })[0];
    if(!item) return;
    closeArtifactsPage();
    stageArtifact(item).then(function(staged){
      composerAttachmentStaged();
      if(!staged) return;
      var input = el('#ccInput');
      if(input) input.focus();
      showBenchToast(chatWs.activeRoomId ? 'Added to your message in ' + (chatWs.activeLabel || 'this chat') + '. Switch chats to send it elsewhere.' : 'Added to your message. Open a chat to send it.');
    });
  }

  // A live app is a saved link, so × just forgets it. A file is moved to the
  // Trash after the person confirms, so it can still be restored.
  function removeArtifact(id){
    var item = artifactsPage.items.filter(function(entry){ return entry.id === id; })[0];
    if(!item) return;
    if(item.kind === 'app'){
      api('/api/artifacts/links/' + encodeURIComponent(id), {method: 'DELETE'}).then(loadArtifacts, loadArtifacts);
      return;
    }
    if(!window.confirm('Move "' + item.name + '" to the Trash?')) return;
    api('/api/artifacts/file?id=' + encodeURIComponent(id), {method: 'DELETE'}).then(function(){
      showBenchToast('"' + item.name + '" moved to the Trash.');
      loadArtifacts();
    }, function(error){
      showBenchToast(error && error.message ? error.message : 'That file could not be moved to the Trash.');
      loadArtifacts();
    });
  }

  function setArtifactsAddOpen(open){
    var form = el('#artifactsAddForm');
    if(!form) return;
    form.hidden = !open;
    var error = el('#artifactsAddError');
    if(error) error.textContent = '';
    if(open){ var url = el('#artifactsAddUrl'); if(url) url.focus(); }
    else form.reset();
  }

  (function wireArtifactsPage(){
    var overlay = el('#artifactsOverlay');
    if(!overlay) return;
    var close = el('#artifactsCloseBtn');
    if(close) close.addEventListener('click', closeArtifactsPage);
    var search = el('#artifactsSearch');
    if(search) search.addEventListener('input', function(){ artifactsPage.query = search.value; renderArtifactsPage(); });
    overlay.addEventListener('click', function(e){
      var filter = e.target.closest('[data-artifacts-filter]');
      if(filter){ artifactsPage.filter = filter.getAttribute('data-artifacts-filter'); renderArtifactsPage(); return; }
      if(e.target.closest('[data-artifacts-add]')){ setArtifactsAddOpen(true); return; }
      var share = e.target.closest('[data-artifact-share]');
      if(share){ shareArtifact(share.getAttribute('data-artifact-share')); return; }
      var remove = e.target.closest('[data-artifact-remove]');
      if(remove){ removeArtifact(remove.getAttribute('data-artifact-remove')); return; }
      var open = e.target.closest('[data-artifact-open]');
      if(open) openArtifact(open.getAttribute('data-artifact-open'));
    });
    var cancel = el('#artifactsAddCancel');
    if(cancel) cancel.addEventListener('click', function(){ setArtifactsAddOpen(false); });
    var form = el('#artifactsAddForm');
    if(form) form.addEventListener('submit', function(e){
      e.preventDefault();
      var url = el('#artifactsAddUrl').value.trim();
      var name = el('#artifactsAddName').value.trim();
      var error = el('#artifactsAddError');
      if(!url){ error.textContent = 'Enter an address, like http://localhost:3000.'; return; }
      if(!/^[a-z][a-z\d+.-]*:\/\//i.test(url)) url = (/^(localhost|127\.0\.0\.1)(:|\/|$)/i.test(url) ? 'http://' : 'https://') + url;
      api('/api/artifacts/links', {method: 'POST', body: {url: url, name: name}}).then(function(res){
        if(res.status !== 201){ error.textContent = res.data && res.data.message || 'That app could not be added.'; return; }
        setArtifactsAddOpen(false);
        loadArtifacts();
      }).catch(function(){ error.textContent = 'That app could not be added.'; });
    });
    // The browser tab menu's Save Page as Artifact and Save Page as App.
    var browser = window.miaDesktop && window.miaDesktop.browser;
    if(browser && browser.onPageSaved) browser.onPageSaved(function(saved){
      if(saved.kind === 'artifact'){
        showBenchToast(saved.failed ? 'That page could not be saved. Try again.' : 'Saved ' + saved.name + ' to Artifacts.');
        if(!saved.failed) loadArtifacts();
        return;
      }
      api('/api/artifacts/links', {method: 'POST', body: {url: saved.url, name: saved.name}}).then(function(res){
        if(res.status !== 201) throw new Error('save_failed');
        showBenchToast('Saved ' + res.data.artifact.name + ' to your apps.');
        loadArtifacts();
      }).catch(function(){ showBenchToast('That page could not be saved as an app. Try again.'); });
    });
  })();

  // Apps page: small web apps people build and share. One page for Solo and a
  // team; a team view adds the team's catalog. Each running app is a sandboxed
  // native view (macos/src/app-sandbox.cjs) placed over the page's pane, with
  // its own tab beside the page's.
  var APPS_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2" y="4" width="20" height="16" rx="2"></rect><path d="M10 4v4"></path><path d="M2 8h20"></path><path d="M6 4v4"></path></svg>';
  var appsPage = {open:false, tabClosed:false, activeTab:'page', tabs:[], query:'', loading:false, error:'', catalogError:'',
    local:[], links:[], catalog:[], scans:{}, publishing:{}, installing:{}, previews:{}, teamId:'', me:'', isAdmin:false};
  var appsUploaders = {};
  var appsScanTimer = null;

  function appsTeamId(){ return hubWorkspace() ? activeWorkspaceKey.slice(4) : ''; }
  function appsDesktop(){ return window.miaDesktop && window.miaDesktop.apps ? window.miaDesktop.apps : null; }

  function openAppsPage(){
    closeLocalBrowser();
    closeAutomationsPage();
    closeArtifactsPage();
    appsPage.open = true;
    appsPage.tabClosed = false;
    document.body.classList.add('browser-collab-mode', 'apps-mode');
    setBrowserSidebarOpen(browserSidebarWanted());
    closeChatThread();
    closeChatTasksPanel();
    chatInfo.mode = 'automations';
    chatInfo.open = false;
    if(!chatWs.activeRoomId && chatWs.gatewayAgent) navigateToAgentChat(chatWs.gatewayAgent, true);
    renderChatInfoPane();
    renderChatHeaderBar();
    renderAppsPage();
    loadApps();
  }
  function closeAppsPage(){
    if(!appsPage.open) return;
    appsPage.open = false;
    clearAppsScanTimer();
    document.body.classList.remove('apps-mode', 'browser-sidebar-open');
    if(!localBrowserState.open) document.body.classList.remove('browser-collab-mode');
    applyLeftPane();
    renderAppsPage();
    renderChatInfoPane();
    renderChatHeaderBar();
  }
  function appsStripTabs(){ return window.MiaAppsPage ? window.MiaAppsPage.stripTabs(appsPage, APPS_ICON) : []; }
  function notifyAppsTabs(){ window.MiaTabStrip.mix.notify('apps', JSON.stringify(appsStripTabs())); }
  window.MiaTabStrip.mix.register('apps', {
    tabs: appsStripTabs,
    attention: function(){ return window.MiaAppsPage.reviewCount(appsPage); },
    close: function(id){
      if(id === 'page'){
        appsPage.tabClosed = true;
        if(appsPage.activeTab === 'page' && appsPage.tabs.length) appsPage.activeTab = appsPage.tabs[0].key;
        else if(appsPage.open && appsPage.activeTab === 'page') closeAppsPage();
      } else closeAppTab(id);
      renderAppsPage();
    },
    show: function(){ if(!appsPage.open) runToolsAction('apps'); },
    select: function(id){ appsPage.activeTab = id === 'page' || appsTabByKey(id) ? id : 'page'; if(id === 'page') appsPage.tabClosed = false; renderAppsPage(); },
    render: notifyAppsTabs,
  });
  function stopLocalServer(id){
    var link = appsPage.links.filter(function(entry){ return entry.id === id; })[0];
    if(!link) return;
    var path = '/api/apps/links/' + encodeURIComponent(id);
    var address = String(link.url).replace(/^https?:\/\//, '').replace(/\/$/, '');
    api(path + '/server').then(function(res){
      var server = res.data || {};
      if(res.status !== 200) throw new Error('lookup');
      if(server.protected){ showBenchToast('Mia needs ' + address + ' to run, so it can’t be stopped here.'); return; }
      if(!server.found){ loadApps(); return; }
      return appConfirm(server.name + ' is running ' + address + '. Stop it? Anything unsaved there may be lost.', 'Stop').then(function(ok){
        if(!ok) return;
        return api(path + '/stop', {method:'POST', body:{pids:server.pids}}).then(function(stop){
          var result = stop.data || {};
          if(stop.status !== 200) throw new Error('stop');
          showBenchToast(result.stopped ? address + ' stopped.' : result.reason === 'denied'
            ? 'Mia isn’t allowed to stop that program. Close it where it’s running.'
            : result.reason === 'changed' ? 'A different program is using ' + address + ' now. Check it and try again.'
            : address + ' is still running. Close it where it’s running.');
          loadApps();
        });
      });
    }).catch(function(){ showBenchToast('Could not stop ' + address + '. Try again.'); });
  }
  function appsTabByKey(key){ return appsPage.tabs.filter(function(tab){ return tab.key === key; })[0] || null; }
  function closeAppTab(key){
    appsPage.activeTab = window.MiaAppsPage.nextTabAfterClose(appsPage, key);
    appsPage.tabs = appsPage.tabs.filter(function(tab){ return tab.key !== key; });
    if(!appsPage.tabs.length) appsPage.tabClosed = false;
    var desktop = appsDesktop();
    if(desktop) desktop.close(key).catch(function(){});
  }
  if(appsDesktop() && appsDesktop().onState) appsDesktop().onState(function(state){
    var tab = state && appsTabByKey(state.key);
    if(!tab) return;
    if(state.blockedLink){
      tab.note = window.MiaAppsPage.blockedLinkNote(state.blockedLink);
      window.clearTimeout(tab.noteTimer);
      tab.noteTimer = window.setTimeout(function(){ tab.note = ''; renderAppsPage(); }, 10000);
      renderAppsPage();
      return;
    }
    tab.status = state.status;
    tab.error = state.error || '';
    renderAppsPage();
  });

  function syncAppsIdentity(){
    var teamId = appsTeamId();
    appsPage.teamId = teamId;
    appsPage.me = hubChat.membership && hubChat.membership.clerk_user_id || '';
    appsPage.isAdmin = !!(hubChat.membership && hubChat.membership.role === 'admin');
    return teamId;
  }
  // The count on the Apps tab needs the catalog before the page is opened. Only
  // an admin asks; a member never has anything to review.
  function loadAppsReviews(){
    var teamId = syncAppsIdentity();
    if(!teamId || !appsPage.isAdmin) return Promise.resolve();
    return loadAppsCatalog(teamId).then(renderAppsPage).then(takeAppsReviewHandoff);
  }
  function takeAppsReviewHandoff(){
    var handoff = null;
    try {
      handoff = JSON.parse(localStorage.getItem('miaAppsReviewHandoff') || 'null');
      if(handoff) localStorage.removeItem('miaAppsReviewHandoff');
    } catch(_reviewHandoffError) {}
    if(handoff && handoff.teamId === appsPage.teamId && Date.now() - Number(handoff.at) < 120000) openAppsReview(handoff.appId);
  }
  function openAppsReview(appId){
    if(!appsPage.open) runToolsAction('apps');
    appsPage.tabClosed = false;
    appsPage.activeTab = 'page';
    appsPage.query = '';
    var search = el('#appsSearch');
    if(search) search.value = '';
    renderAppsPage();
    var row = document.querySelector('[data-app-review="' + String(appId).replace(/[^a-f0-9]/g, '') + '"]');
    if(row) row.scrollIntoView({block: 'center'});
  }
  function onAppReviewEvent(event){
    var review = window.MiaAppsPage && window.MiaAppsPage.reviewFromEvent(event, !!(hubChat.membership && hubChat.membership.role === 'admin'));
    if(!review) return;
    var teamId = syncAppsIdentity();
    if(!teamId) return;
    loadAppsCatalog(teamId).then(function(){
      renderAppsPage();
      var app = appsPage.catalog.filter(function(entry){ return entry.id === review.appId; })[0] || null;
      // Decided or removed before this got here.
      if(!window.MiaAppsPage.isWaitingForReview(app)) return;
      var text = window.MiaAppsPage.reviewNotice(app), go = function(){ openAppsReview(review.appId); };
      showBenchToast(text, go);
      if(appInForeground() || !desktopNotificationsEnabled()) return;
      if(nativeDesktopNotifications()){ showNativeNotification({title: 'Mia', body: text, tag: window.MiaAppsPage.reviewTag(review.appId)}); return; }
      try {
        var notification = new window.Notification('Mia', {body: text, tag: window.MiaAppsPage.reviewTag(review.appId)});
        notification.onclick = function(){ window.focus(); notification.close(); go(); };
      } catch(_reviewNotificationError) {}
    });
  }

  function loadApps(){
    var teamId = syncAppsIdentity();
    if(!teamId){ appsPage.catalog = []; appsPage.catalogError = ''; }
    appsPage.loading = true;
    appsPage.error = '';
    renderAppsPage();
    var local = api('/api/apps/local').then(function(res){
      if(res.status !== 200) throw new Error('local');
      appsPage.local = Array.isArray(res.data.apps) ? res.data.apps : [];
      appsPage.links = Array.isArray(res.data.links) ? res.data.links : [];
    }).catch(function(){ appsPage.error = 'The apps on this computer could not be loaded. Try again.'; });
    var catalog = teamId ? loadAppsCatalog(teamId) : Promise.resolve();
    Promise.all([local, catalog]).then(function(){
      appsPage.loading = false;
      renderAppsPage();
    });
  }
  // Your own apps still work when the team can't be reached, so this only says so.
  function loadAppsCatalog(teamId){
    return hubCall('GET', '/v1/teams/' + teamId + '/apps').then(function(reply){
      if(teamId !== appsTeamId()) return;
      appsPage.catalog = window.MiaAppsPage.normalizeCatalog(reply);
      appsPage.catalogError = '';
      checkAppsScans(teamId);
    }).catch(function(){
      if(teamId === appsTeamId()) appsPage.catalogError = "Your company's apps could not be loaded. Check your connection, then try again.";
    });
  }
  function clearAppsScanTimer(){ if(appsScanTimer){ window.clearTimeout(appsScanTimer); appsScanTimer = null; } }
  // Asks about pending files until each has a verdict, while the page is open.
  function checkAppsScans(teamId){
    clearAppsScanTimer();
    var ids = window.MiaAppsPage.filesToCheck(appsPage.catalog, appsPage.scans);
    if(!ids.length || !appsPage.open || !window.MiaTeamFiles) return;
    var client = window.MiaTeamFiles.createClient({teamId: teamId, call: hubCall});
    Promise.all(ids.map(function(id){
      return client.status(id).then(function(reply){ appsPage.scans[id] = window.MiaTeamFiles.scanVerdict(reply); }, function(){ /* asked again below */ });
    })).then(function(){
      renderAppsPage();
      if(appsPage.open && window.MiaAppsPage.filesToCheck(appsPage.catalog, appsPage.scans).length) appsScanTimer = window.setTimeout(function(){ checkAppsScans(teamId); }, 5000);
    });
  }

  function renderAppsPage(){
    var overlay = el('#appsOverlay');
    if(!overlay) return;
    notifyAppsTabs();
    overlay.hidden = !appsPage.open;
    overlay.setAttribute('aria-hidden', appsPage.open ? 'false' : 'true');
    overlay.classList.toggle('open', appsPage.open);
    var tab = appsTabByKey(appsPage.activeTab);
    var body = el('#appsBody'), host = el('#appsPaneHost'), filter = el('#appsFilterRow');
    if(body) body.hidden = !!tab;
    if(filter) filter.hidden = !!tab;
    if(host) host.hidden = !tab;
    var paneNote = el('#appsPaneNote');
    if(paneNote){
      paneNote.hidden = !(tab && tab.note);
      paneNote.innerHTML = tab && tab.note ? '<span>' + esc(tab.note) + '</span><button type="button" class="artifacts-bar-text-btn" data-app-note-dismiss="' + esc(tab.key) + '">Dismiss</button>' : '';
    }
    if(appsPage.open && window.MiaAppsPage){
      if(!tab && body) body.innerHTML = window.MiaAppsPage.bodyHtml(appsPage, esc);
      if(tab && host) host.innerHTML = window.MiaAppsPage.runHtml(tab, esc);
    }
    syncAppPane();
  }
  // Native views sit above HTML, so the running app steps aside for anything
  // that covers the page: the search bar's list, a tab menu, Settings, a
  // confirmation. Whatever is on top at a few spots across the pane says so.
  function appPaneCovered(host){
    if(!document.body.classList.contains('apps-mode')) return true;
    var box = host.getBoundingClientRect();
    if(box.width < 1 || box.height < 1) return true;
    var inset = 6;
    return [0, 0.33, 0.66, 1].some(function(across){
      return [0, 0.5, 1].some(function(down){
        var top = document.elementFromPoint(box.left + inset + (box.width - inset * 2) * across, box.top + inset + (box.height - inset * 2) * down);
        return !!top && !host.contains(top) && !top.contains(host);
      });
    });
  }
  var appPaneShown = '', appPaneWatch = null;
  function syncAppPane(){
    var desktop = appsDesktop();
    if(!desktop || !appsPage) return;
    var host = el('#appsPaneHost'), tab = appsTabByKey(appsPage.activeTab);
    var running = appsPage.open && !!tab && !!host;
    // Nothing tells the page when a dialog opens somewhere else, so it keeps looking.
    if(running && !appPaneWatch) appPaneWatch = window.setInterval(syncAppPane, 400);
    if(!running && appPaneWatch){ window.clearInterval(appPaneWatch); appPaneWatch = null; }
    var box = running && !appPaneCovered(host) ? host.getBoundingClientRect() : null;
    var rect = box ? {x: box.x, y: box.y, width: box.width, height: box.height} : null;
    var next = rect ? tab.key + JSON.stringify(rect) : '';
    if(next === appPaneShown) return;
    appPaneShown = next;
    desktop.layout(rect ? tab.key : '', rect).catch(function(){});
  }
  (function watchAppPane(){
    var host = el('#appsPaneHost');
    if(!host || !appsDesktop()) return;
    if(window.ResizeObserver) new ResizeObserver(syncAppPane).observe(host);
    window.addEventListener('resize', syncAppPane);
    new MutationObserver(syncAppPane).observe(document.body, {attributes: true, attributeFilter: ['class']});
    var suggest = el('#localBrowserUrlSuggest');
    if(suggest) new MutationObserver(syncAppPane).observe(suggest, {attributes: true, attributeFilter: ['hidden']});
  })();

  function showAppTab(key, name, source){
    if(!appsTabByKey(key)) appsPage.tabs.push({key: key, name: name, source: source, status: 'loading', error: ''});
    appsPage.activeTab = key;
    appPaneShown = '';
    renderAppsPage();
  }
  function openLocalApp(id){
    var item = appsPage.local.filter(function(entry){ return entry.id === id; })[0], desktop = appsDesktop();
    if(!item) return;
    if(!desktop){ showBenchToast('Apps run in the Mia desktop app.'); return; }
    desktop.open({kind: 'local', id: id}).then(function(reply){
      if(!reply || !reply.ok){ showBenchToast(reply && reply.error || 'That app could not be opened.'); return; }
      showAppTab(reply.key, item.name, {kind: 'local', id: id});
    }).catch(function(){ showBenchToast('That app could not be opened.'); });
  }
  function openAppAddress(url){
    var browser = window.miaDesktop && window.miaDesktop.browser;
    if(!browser || !browser.command){ showBenchToast('Apps open in the Mia desktop app.'); return; }
    closeAppsPage();
    openAddressInBrowserTab(url, 'That app could not be opened.');
  }
  // The backend's app routes that carry bytes, which api() would turn into JSON.
  function appsBytes(path, options){
    return fetch(path, Object.assign({credentials: 'include'}, options, {headers: Object.assign({'X-MiaOS-Workspace': activeWorkspaceKey}, options.headers || {})}));
  }
  function appsIdentityQuery(identity, sha256){
    return 'teamId=' + encodeURIComponent(identity.teamId) + '&appId=' + encodeURIComponent(identity.appId) + '&version=' + encodeURIComponent(identity.version) + '&sha256=' + encodeURIComponent(sha256);
  }
  // Gets one version onto this computer. A preview uses the same checks and the
  // same code, in a folder of its own: `progress` is told how far the download got.
  function installTeamVersion(teamId, appId, version, preview, progress){
    var suffix = preview ? '&preview=1' : '';
    var client = window.MiaTeamFiles.createClient({teamId: teamId, call: hubCall});
    return window.MiaAppsPage.installVersion({teamId: teamId, appId: appId, version: version,
      isInstalled: function(identity, sha256){
        return api('/api/apps/installed?' + appsIdentityQuery(identity, sha256) + suffix).then(function(res){ return res.status === 200 && res.data.installed === true; });
      },
      download: function(file){
        return window.MiaTeamFiles.downloadFile({client: client, file: file, onProgress: function(done, total){ progress(total ? Math.floor(done * 100 / total) : null); }});
      },
      install: function(identity, sha256, blob){
        return appsBytes('/api/apps/install?' + appsIdentityQuery(identity, sha256) + suffix, {method: 'POST', headers: {'Content-Type': 'application/octet-stream'}, body: blob}).then(function(res){
          if(res.status === 201) return;
          return res.json().catch(function(){ return {}; }).then(function(data){ throw new Error(data.message || 'That app could not be installed.'); });
        });
      },
    });
  }
  // An admin looks before approving. A link opens only here, on this click.
  function previewTeamApp(id){
    var app = appsPage.catalog.filter(function(entry){ return entry.id === id; })[0], teamId = appsPage.teamId;
    if(!appsPage.isAdmin || !window.MiaAppsPage.isWaitingForReview(app)) return;
    var version = app.pending;
    if(version.kind === 'link'){ openAppAddress(version.url); return; }
    var desktop = appsDesktop();
    if(!desktop || !window.MiaTeamFiles){ showBenchToast('Apps run in the Mia desktop app.'); return; }
    if(appsPage.previews[id] && appsPage.previews[id].loading) return;
    var preview = appsPage.previews[id] = {version: version.version, loading: true};
    renderAppsPage();
    installTeamVersion(teamId, id, version, true, function(percent){
      if(preview.percent !== percent){ preview.percent = percent; renderAppsPage(); }
    }).then(function(identity){
      return api('/api/apps/installed/files?' + appsIdentityQuery(identity, version.sha256) + '&preview=1').then(function(res){
        if(res.status !== 200) throw new Error('That app could not be opened.');
        preview.files = Array.isArray(res.data.files) ? res.data.files : [];
        preview.totalBytes = res.data.totalBytes;
        return desktop.open(Object.assign({kind: 'preview'}, identity));
      });
    }).then(function(reply){
      if(!reply || !reply.ok) throw new Error(reply && reply.error || 'That app could not be opened.');
      preview.loading = false;
      showAppTab(reply.key, 'Preview: ' + app.name, {kind: 'preview', appId: id});
    }).catch(function(error){
      preview.loading = false;
      preview.error = window.MiaAppsPage.openErrorMessage(error, app.publisher && app.publisher.name);
      renderAppsPage();
    });
  }
  function openTeamApp(id){
    var app = appsPage.catalog.filter(function(entry){ return entry.id === id; })[0], teamId = appsPage.teamId;
    if(!app || !app.live || appsPage.installing[id] && !appsPage.installing[id].error) return;
    if(app.live.kind === 'link'){ openAppAddress(app.live.url); return; }
    var desktop = appsDesktop();
    if(!desktop || !window.MiaTeamFiles){ showBenchToast('Apps run in the Mia desktop app.'); return; }
    appsPage.installing[id] = {};
    renderAppsPage();
    installTeamVersion(teamId, id, app.live, false, function(percent){
      if(appsPage.installing[id] && appsPage.installing[id].percent !== percent){ appsPage.installing[id].percent = percent; renderAppsPage(); }
    }).then(function(identity){
      return desktop.open(Object.assign({kind: 'team'}, identity));
    }).then(function(reply){
      if(!reply || !reply.ok) throw new Error(reply && reply.error || 'That app could not be opened.');
      delete appsPage.installing[id];
      showAppTab(reply.key, app.name, {kind: 'team', appId: id});
    }).catch(function(error){
      appsPage.installing[id] = {error: window.MiaAppsPage.openErrorMessage(error, app.publisher && app.publisher.name)};
      renderAppsPage();
    });
  }
  function appsUploader(teamId){
    if(appsUploaders[teamId]) return appsUploaders[teamId];
    var client = window.MiaTeamFiles.createClient({teamId: teamId, call: hubCall});
    var storage = (function(){ try { return window.localStorage; } catch(_appsStorageError){ return null; } })();
    var store = window.MiaTeamFiles.createStore(storage || {getItem: function(){ return null; }, setItem: function(){}});
    appsUploaders[teamId] = window.MiaAppsPage.createUploader(window.MiaTeamFiles.createManager, {client: client, store: store, teamId: teamId, space: {kind: 'app', id: teamId}});
    return appsUploaders[teamId];
  }
  function newAppsId(){ return window.MiaAppsPage.newAppId(function(bytes){ return window.crypto.getRandomValues(bytes); }); }
  function publishLocalApp(id){
    var teamId = appsPage.teamId;
    if(!teamId || !window.MiaTeamFiles) return;
    var folder = appsPage.local.filter(function(entry){ return entry.id === id; })[0];
    var link = appsPage.links.filter(function(entry){ return entry.id === id; })[0];
    var item = folder || link;
    if(!item || appsPage.publishing[id] && appsPage.publishing[id].step) return;
    var existing = window.MiaAppsPage.publishedAs(appsPage.catalog, item.name, appsPage.me);
    var setStep = function(step){ appsPage.publishing[id] = {step: step}; renderAppsPage(); };
    var publishing;
    if(link){
      setStep('publishing');
      publishing = window.MiaAppsPage.publishLink({call: hubCall, teamId: teamId, existing: existing, newId: newAppsId, link: link});
    } else {
      publishing = window.MiaAppsPage.publishFolder({call: hubCall, teamId: teamId, existing: existing, newId: newAppsId, item: folder, onStep: setStep,
        client: window.MiaTeamFiles.createClient({teamId: teamId, call: hubCall}), uploader: appsUploader(teamId), verdict: window.MiaTeamFiles.scanVerdict,
        sleep: function(ms){ return new Promise(function(done){ window.setTimeout(done, ms); }); },
        previewBundle: function(appId){
          return api('/api/apps/local/preview', {method: 'POST', body: {id: appId, name: folder.name}}).then(function(res){
            if(res.status !== 200) throw new Error(res.data.message || 'That app could not be checked.');
            return res.data;
          });
        },
        confirmBundle: function(files){
          return appConfirm('Publish these ' + files.length + ' files to the company?\n\n' + files.join('\n'), 'Publish files', {fileList: true});
        },
        buildBundle: function(appId, sha256){
          return appsBytes('/api/apps/local/bundle', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({id: appId, name: folder.name, sha256: sha256})}).then(function(res){
            if(res.status !== 200) return res.json().catch(function(){ return {}; }).then(function(data){ throw new Error(data.message || 'That app could not be packed.'); });
            var filename = decodeURIComponent(res.headers.get('X-Mia-App-Filename') || 'app.miaapp');
            return res.blob().then(function(blob){ return {file: new File([blob], filename, {type: 'application/octet-stream'})}; });
          });
        }});
    }
    publishing.then(function(result){
      delete appsPage.publishing[id];
      if(result && result.cancelled) return renderAppsPage();
      showBenchToast(appsPage.isAdmin ? '"' + item.name + '" is published.' : '"' + item.name + '" is waiting for an admin to approve it.');
      return loadAppsCatalog(teamId);
    }).then(renderAppsPage).catch(function(error){
      appsPage.publishing[id] = {error: window.MiaAppsPage.errorMessage(error, 'That app could not be published.')};
      renderAppsPage();
    });
  }
  function decideTeamApp(id, decision){
    var app = appsPage.catalog.filter(function(entry){ return entry.id === id; })[0], teamId = appsPage.teamId;
    if(!window.MiaAppsPage.isWaitingForReview(app)) return;
    (decision === 'approve' ? appConfirm(window.MiaAppsPage.approveMessage(app), 'Approve for everyone') : Promise.resolve(true)).then(function(yes){
      if(!yes) return null;
      return hubCall('POST', '/v1/teams/' + teamId + '/apps/' + id + '/versions/' + app.pending.version + '/' + decision, {}).then(function(){
        return loadAppsCatalog(teamId);
      });
    }).then(renderAppsPage).catch(function(error){
      showBenchToast(window.MiaAppsPage.errorMessage(error, 'That did not work. Try again.'));
      loadAppsCatalog(teamId).then(renderAppsPage);
    });
  }
  function archiveTeamApp(id){
    var app = appsPage.catalog.filter(function(entry){ return entry.id === id; })[0], teamId = appsPage.teamId;
    if(!app) return;
    appConfirm('Remove "' + app.name + '" from your company? Nobody on your company will be able to open it from here.', 'Remove').then(function(yes){
      if(!yes) return null;
      return hubCall('DELETE', '/v1/teams/' + teamId + '/apps/' + id, {}).then(function(){ return loadAppsCatalog(teamId); }).then(renderAppsPage);
    }).catch(function(error){ showBenchToast(window.MiaAppsPage.errorMessage(error, 'That did not work. Try again.')); });
  }
  // Puts the request in the composer so the person can say what the app is for.
  function buildAppWithBot(){ draftInChat(window.MiaAppsPage.BUILD_PROMPT); }
  // Puts a ready request in the message box, with the part to fill in selected.
  function draftInChat(prompt){
    closeAppsPage();
    closeArtifactsPage();
    var input = el('#ccInput');
    if(!input) return;
    input.value = prompt;
    input.dispatchEvent(new Event('input', {bubbles: true}));
    input.focus();
    var at = input.value.indexOf('[say what it should do]');
    if(at >= 0) input.setSelectionRange(at, at + '[say what it should do]'.length);
  }
  (function wireAppsPage(){
    var overlay = el('#appsOverlay');
    if(!overlay) return;
    var close = el('#appsCloseBtn');
    if(close) close.addEventListener('click', closeAppsPage);
    var search = el('#appsSearch');
    if(search) search.addEventListener('input', function(){ appsPage.query = search.value; renderAppsPage(); });
    var actions = {
      'data-app-open-local': openLocalApp,
      'data-app-open-team': openTeamApp,
      'data-app-publish': publishLocalApp,
      'data-app-approve': function(id){ decideTeamApp(id, 'approve'); },
      'data-app-reject': function(id){ decideTeamApp(id, 'reject'); },
      'data-app-archive': archiveTeamApp,
      'data-app-preview': previewTeamApp,
      'data-app-note-dismiss': function(key){ var tab = appsTabByKey(key); if(tab){ tab.note = ''; renderAppsPage(); } },
      'data-app-stop-link': stopLocalServer,
      'data-app-open-link': function(id){ var link = appsPage.links.filter(function(entry){ return entry.id === id; })[0]; if(link) openAppAddress(link.url); },
      'data-app-reload': function(key){ var tab = appsTabByKey(key), desktop = appsDesktop(); if(tab && desktop){ tab.status = 'loading'; desktop.reload(key).catch(function(){}); renderAppsPage(); } },
    };
    overlay.addEventListener('click', function(e){
      if(e.target.closest('[data-app-build]')){ buildAppWithBot(); return; }
      if(e.target.closest('[data-apps-retry]')){ loadApps(); return; }
      if(e.target.closest('[data-app-add-link]')){ runToolsAction('artifacts'); setArtifactsAddOpen(true); return; }
      for(var name in actions){
        var target = e.target.closest('[' + name + ']');
        if(target){ actions[name](target.getAttribute(name)); return; }
      }
    });
  })();

  (function wireAutomationsPage(){
    var overlay = el('#automationsOverlay');
    if(!overlay) return;
    els('[data-automations-group]', overlay).forEach(function(button){
      button.addEventListener('click', function(){
        automationsPage.group = button.getAttribute('data-automations-group') === 'bot' ? 'bot' : 'status';
        try { localStorage.setItem(AUTOMATIONS_GROUP_KEY, automationsPage.group); } catch(_automationsGroupError) {}
        renderAutomationsPage();
      });
    });
    var close = el('#automationsCloseBtn');
    if(close) close.addEventListener('click', closeAutomationsPage);
    window.addEventListener('mia-bots-changed', function(){ if(automationsPage.open) renderAutomationsPage(); });
    wireAutomationsAdd();
  })();

  // The "+" on the Automations page: pick the bot that will own the new
  // automation, then its chat opens with the "New automation" editor beside it.
  function wireAutomationsAdd(){
    var button = el('#automationsAddBtn');
    var menu = el('#automationsAddMenu');
    if(!button || !menu) return;
    function setMenuOpen(open){
      menu.hidden = !open;
      button.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
    function startNewAutomation(botId){
      setMenuOpen(false);
      var agent = (chatWs.allAgents || []).filter(function(item){ return item && String(item.id) === String(botId); })[0];
      if(agent) navigateToAgentChat(agent, true);
      openAutomationDetail(botId, null, true);
    }
    button.addEventListener('click', function(e){
      e.stopPropagation();
      if(!menu.hidden){ setMenuOpen(false); return; }
      var bots = (chatWs.botRecords || []).filter(Boolean);
      if(bots.length === 1 && botAutomationList(bots[0]).length < 10){ startNewAutomation(bots[0].id); return; }
      menu.innerHTML = bots.length ? '<div class="automations-add-title">New automation for…</div>' + bots.map(function(bot){
        var full = botAutomationList(bot).length >= 10;
        return '<button type="button" role="menuitem" class="automations-add-item" data-automations-add-bot="' + esc(bot.id) + '"' + (full ? ' disabled title="This bot already has 10 automations"' : '') + '>' +
          agentAvatarHtml(bot.name || 'Bot', bot.id, 20, 'static', bot.avatarColor || null) + '<span>' + esc(bot.name || 'Bot') + '</span></button>';
      }).join('') : '<div class="automations-add-empty">No bots yet. Ask Mia to create one, then add its automation here.</div>';
      els('[data-automations-add-bot]', menu).forEach(function(item){
        item.addEventListener('click', function(){ startNewAutomation(item.getAttribute('data-automations-add-bot')); });
      });
      setMenuOpen(true);
    });
    document.addEventListener('click', function(e){ if(!menu.hidden && !menu.contains(e.target)) setMenuOpen(false); });
    document.addEventListener('keydown', function(e){ if(e.key === 'Escape' && !menu.hidden) setMenuOpen(false); });
  }

  // Tab groups can belong to a bot. While the browser is open, the chat pane
  // follows the tab in front: a bot's group shows that bot's chat, any other
  // tab shows Mia. It switches only when the tab in front (or its owner)
  // changes, so picking another chat by hand sticks until then.
  var browserFollowKey = '';
  var browserFollowState = null;
